using Microsoft.Kiota.Abstractions;
using Microsoft.Kiota.Abstractions.Authentication;
using Microsoft.Kiota.Http.HttpClientLibrary;
using Sap.Cloud.Sdk.CloudPlatform.Connectivity;

namespace Sap.Cloud.Sdk.DataModel.OpenApi;

/// <summary>
/// Creates Kiota request adapters that send requests to an SAP destination. Use them with OpenAPI clients generated by
/// <see href="https://learn.microsoft.com/openapi/kiota/">Kiota</see>.
/// </summary>
/// <remarks>
/// <para>
/// Replaces the Java SDK's <c>openapi-core</c> runtime (<c>ApiClient</c>, <c>AbstractOpenApiService</c>) and its
/// generator: in .NET, clients are generated with Kiota (see <c>docs/OPENAPI.md</c>) and run on top of this adapter.
/// </para>
/// <para>
/// Authentication, proxies, TLS and CSRF tokens are handled by the destination's HTTP pipeline
/// (<see cref="HttpClientAccessor"/>); Kiota's own authentication provider is therefore anonymous.
/// </para>
/// </remarks>
/// <example>
/// <code>
/// var client = new SodaStoreClient(OpenApiRequestAdapterFactory.Create(destination));
/// var sodas = await client.Sodas.GetAsync();
/// </code>
/// </example>
public static class OpenApiRequestAdapterFactory
{
    /// <summary>Creates an adapter for a destination.</summary>
    /// <param name="destination">The destination; its URL is the base URL of the API.</param>
    /// <returns>The request adapter.</returns>
    public static IRequestAdapter Create(IHttpDestinationProperties destination)
    {
        ArgumentNullException.ThrowIfNull(destination);
        return Create(HttpClientAccessor.GetHttpClient(destination), destination.Uri);
    }

    /// <summary>Creates an adapter for the destination with the given name.</summary>
    /// <param name="destinationName">The destination name, resolved via <see cref="DestinationAccessor"/>.</param>
    /// <param name="cancellationToken">Cancels the lookup.</param>
    /// <returns>The request adapter.</returns>
    public static async Task<IRequestAdapter> CreateAsync(string destinationName, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(destinationName);
        var destination = await DestinationAccessor.GetDestinationAsync(destinationName, cancellationToken).ConfigureAwait(false);
        return Create(destination as IHttpDestinationProperties
            ?? throw new CloudPlatform.Connectivity.Exceptions.DestinationAccessException(
                destinationName, $"Destination '{destinationName}' is not an HTTP destination."));
    }

    /// <summary>Creates an adapter that sends requests with the given client.</summary>
    /// <param name="httpClient">The HTTP client, typically from <see cref="HttpClientAccessor"/> or <c>IHttpClientFactory</c>.</param>
    /// <param name="baseUrl">The base URL of the API; defaults to <see cref="HttpClient.BaseAddress"/>.</param>
    /// <returns>The request adapter.</returns>
    public static IRequestAdapter Create(HttpClient httpClient, Uri? baseUrl = null)
    {
        ArgumentNullException.ThrowIfNull(httpClient);
        var adapter = new HttpClientRequestAdapter(new AnonymousAuthenticationProvider(), httpClient: httpClient);
        var effectiveBase = baseUrl ?? httpClient.BaseAddress;
        if (effectiveBase is not null)
        {
            adapter.BaseUrl = effectiveBase.AbsoluteUri.TrimEnd('/');
        }
        return adapter;
    }
}
